You are given an integer array queries[], where each element represents a query value n. For every n in the array, determine how many numbers less than or equal to n have exactly 3 divisors.Examples: Input: queries[] = [6]Output: [1]Explanation: There is only one number 4 which has exactly three divisors 1, 2 and 4 and less than equal to 6.Input: query[] = [3, 10]Output: [0, 2]Explanation: For query[0], the answer is 0. For query[1], there are two numbers 4 and 9 having exactly 3 divisors.Try It YourselfTable of Content[Naive Approach] Divisor Count Check - O(q × n × √n) Time and O(1) Space[Better Approach] Prime Square Property - O(q × √n × √√n) Time and O(1) Space[Expected Approach] Sieve with Prefix Count - O(√M log log √M + q) Time and O(√M) Space[Naive Approach] Divisor Count Check - O(q × n × √n) Time and O(1) SpaceFor each query, iterate all numbers from 1 to n and count divisors of each number. If divisor count equals 3, increment total.For each query, initialize total = 0For num from 1 to n, compute divisor countIf divisor count equals 3, increment totalStore total in answer arrayReturn answer array
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Count total divisors of a number
int divisorCount(int num) {
    int cnt = 0;

    for (int i = 1; i <= num; i++) {
        if (num % i == 0) {
            cnt++;
        }
    }

    return cnt;
}

// For each query, count numbers having exactly 3 divisors
vector<int> threeDivisors(vector<int>& queries) {
    vector<int> ans;

    for (int n : queries) {

        int total = 0;

        // Check every number from 1 to n
        for (int num = 1; num <= n; num++) {

            if (divisorCount(num) == 3) {
                total++;
            }
        }

        ans.push_back(total);
    }

    return ans;
}

int main() {
    vector<int> queries = {6, 10, 100};

    vector<int> ans = threeDivisors(queries);

    for (int x : ans) {
        cout << x << " ";
    }

    return 0;
}


