[Expected Approach] Sieve with Prefix Count - O(√M log log √M + q) Time and O(√M) SpaceA number has exactly 3 divisors only if it is square of a prime. Use Sieve to mark primes up to √M, build prefix count, and answer each query in O(1).Find maximum query value MCompute limit = √M and run Sieve up to limitBuild prefixPrime array where prefixPrime[i] = number of primes ≤ iFor each query n, compute root = √n and return prefixPrime[root]
            C++

    #include <iostream>
#include <vector>
#include <cmath>
using namespace std;

vector<int> threeDivisors(vector<int>& queries) {

    // Find maximum query value
    int maxQuery = 0;

    for (int x : queries) {
        maxQuery = max(maxQuery, x);
    }

    // We only need primes up to sqrt(maxQuery)
    int limit = sqrt(maxQuery);

    // Sieve of Eratosthenes
    vector<bool> isPrime(limit + 1, true);
    isPrime[0] = isPrime[1] = false;

    for (int i = 2; i * i <= limit; i++) {

        if (isPrime[i]) {

            // Mark multiples as non-prime
            for (int j = i * i; j <= limit; j += i) {
                isPrime[j] = false;
            }
        }
    }

    // prefixPrime[i] = number of primes <= i
    vector<int> prefixPrime(limit + 1, 0);

    for (int i = 1; i <= limit; i++) {
        prefixPrime[i] = prefixPrime[i - 1] + (isPrime[i] ? 1 : 0);
    }

    vector<int> ans;

    for (int n : queries) {

        // Numbers having exactly 3 divisors
        // = prime squares <= n
        int root = sqrt(n);

        ans.push_back(prefixPrime[root]);
    }

    return ans;
}

int main() {

    vector<int> queries = {6, 10, 100};

    vector<int> ans = threeDivisors(queries);

    for (int x : ans) {
        cout << x << " ";
    }

    return 0;
}


